const pages=$input.all().map(i=>i.json||{});
if(pages.some(p=>!Array.isArray(p.invoice_items)))throw new Error('Respuesta de catálogo Nimbo inválida');
if(pages.length>=50 && pages[pages.length-1].invoice_items.length>=100)throw new Error('Catálogo incompleto: revisar límite de páginas');
const seen=new Set();
const arr=pages.flatMap(p=>p.invoice_items).filter(x=>{if(!x||!x.id||seen.has(String(x.id)))return false;seen.add(String(x.id));return true;});
const productos=arr.filter(x=>x.active!==false).map(x=>({
 id:x.id,nombre:x.description||'',precio:Number(x.value||0)/100,activo:x.active!==false,
 stock:Number(x.stock_total??0),stockable:Boolean(x.stockable),sku:x.sku||'',
 accounting_type:x.accounting_type||'',organization_id:x.organization_id??null,no_locations:x.no_locations||''
})).filter(x=>x.nombre).sort((a,b)=>a.nombre.localeCompare(b.nombre,'es'));
return [{json:{ok:true,total:productos.length,productos}}];
